<?php require __DIR__.'/includes/bootstrap.php'; $active='contact'; $pageTitle='Contact Benaki Fabrics'; require __DIR__.'/includes/header.php'; ?><section class="page-hero"><div class="max-w-7xl mx-auto px-4 py-16"><span>CONTACT US</span><h1>Let’s help you find the right fabric.</h1><p>Send an enquiry or request availability, pricing and delivery information.</p></div></section><section class="max-w-6xl mx-auto px-4 py-14 grid lg:grid-cols-2 gap-10"><div><h2 class="text-3xl font-bold">We are here to help</h2><p class="text-slate-600 mt-3">For orders, bulk supply and general enquiries, reach us using the details below.</p><div class="mt-8 space-y-5"><div><b>Call / WhatsApp</b><p class="text-slate-600">08133314846 · 09069351146</p></div><div><b>Location</b><p class="text-slate-600">Calabar, Cross River State</p></div><div><b>Delivery</b><p class="text-slate-600">South East & South South Nigeria</p></div></div></div><div class="bg-white rounded-2xl border p-6 shadow-sm"><form id="contactForm" class="space-y-4"><input type="text" name="website" class="hidden" tabindex="-1"><div><label class="label">Full Name *</label><input name="fullname" required class="input"></div><div class="grid sm:grid-cols-2 gap-4"><div><label class="label">Phone</label><input name="phone" class="input"></div><div><label class="label">Email</label><input name="email" type="email" class="input"></div></div><div><label class="label">Message *</label><textarea name="message" required rows="6" class="input"></textarea></div><div id="contactResult" class="text-sm"></div><button class="w-full bg-benaki-navy text-white py-3 rounded-xl font-bold">Send Message</button></form></div></section><script>document.getElementById('contactForm').addEventListener('submit',async e=>{e.preventDefault();let r=document.getElementById('contactResult');try{let x=await fetch('ajax/contact.php',{method:'POST',body:new FormData(e.target),headers:{Accept:'application/json'}}),d=await x.json();if(!d.ok)throw new Error(d.message);r.className='text-emerald-700';r.textContent=d.message;e.target.reset();}catch(err){r.className='text-red-600';r.textContent=err.message||'Unable to send message.';}});</script><?php require __DIR__.'/includes/footer.php'; ?>
